import type { ActiveBackend } from "./types.js";

export interface I420Planes {
  y: Uint8Array;
  u: Uint8Array;
  v: Uint8Array;
  yStride: number;
  uStride: number;
  vStride: number;
  yWidth: number;
  uWidth: number;
  vWidth: number;
  yHeight: number;
  uHeight: number;
  vHeight: number;
  yBitDepth: number;
  uBitDepth: number;
  vBitDepth: number;
  /** HEVC VUI video_full_range_flag. Unspecified streams default to limited range. */
  fullRange?: boolean;
  /** HEVC VUI matrix_coeffs value (ITU-T H.273 / ISO/IEC 23091-2). */
  matrixCoefficients?: number;
}

export interface UnifiedVideoFrameInit {
  timestamp: number;
  duration?: number;
  codedWidth: number;
  codedHeight: number;
  displayWidth?: number;
  displayHeight?: number;
  backend: ActiveBackend;
  nativeFrame?: VideoFrame;
  planes?: I420Planes;
}

export class UnifiedVideoFrame {
  readonly timestamp: number;
  readonly duration: number | undefined;
  readonly codedWidth: number;
  readonly codedHeight: number;
  readonly displayWidth: number;
  readonly displayHeight: number;
  readonly backend: ActiveBackend;
  _nativeFrame: VideoFrame | undefined;
  _planes: I420Planes | undefined;
  private _closed = false;

  constructor(init: UnifiedVideoFrameInit) {
    this.timestamp = init.timestamp;
    this.duration = init.duration;
    this.codedWidth = init.codedWidth;
    this.codedHeight = init.codedHeight;
    this.displayWidth = init.displayWidth ?? init.codedWidth;
    this.displayHeight = init.displayHeight ?? init.codedHeight;
    this.backend = init.backend;
    this._nativeFrame = init.nativeFrame;
    this._planes = init.planes;
  }

  get closed(): boolean {
    return this._closed;
  }

  /** Native WebCodecs frame, available only while a WebCodecs frame is open. */
  get nativeFrame(): VideoFrame | undefined {
    return this._nativeFrame;
  }

  /** Decoded I420 planes, available only while a WASM frame is open. */
  get planes(): Readonly<I420Planes> | undefined {
    return this._planes;
  }

  close(): void {
    if (this._closed) return;
    this._closed = true;
    this._nativeFrame?.close();
    this._nativeFrame = undefined;
    this._planes = undefined;
  }
}
